import{z as n,x as s,o as t,c as d,q as r,j as A,D as e,d as a,s as o,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const K=JSON.parse('{"title":"成本优化案例","description":"","frontmatter":{"title":"成本优化案例","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lc-cost-case.md","filePath":"llm/lc-cost-case.md","lastUpdated":1791413859000}'),m={name:"llm/lc-cost-case.md"};function p(c,E,h,f,D,C){const B=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="成本优化案例" tabindex="-1">成本优化案例 <a class="header-anchor" href="#成本优化案例" aria-label="Permalink to &quot;成本优化案例&quot;">​</a></h1><div class="epigraph"><p>成本优化按数量级排顺序：先让问题变小，再让常数变小，最后才搬东西。</p><footer>—— 据 Pope et al., 2022 的会计口径与 Zhong et al., DistServe, OSDI 2024 的资源分离经验整理</footer></div><p><a href="/llm/lc-eval-serving">上一课</a>把评测立成门禁。本课是课程的第一次综合：把前面八课的杠杆装进同一个案例，按顺序走一遍。案例设定：企业合同助手，十万份合同，日均数千问。基线配置是「每问把召回的 top-50 份全文推进窗口」——单问约 500K token，从<a href="/llm/lc-memory-account">显存账</a>上就不成立。下面按杠杆排序走六步，每步先报账，再过<a href="/llm/lc-eval-serving">门禁</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基线的账不用细算就出局：500K token 的单问 KV（FP16）是 64 GiB，比一张卡扣掉权重后的全部余量还大；即便装进多卡，TTFT 与排队也会把服务拖死。工程上的常见错误不是不优化，而是<strong>乱序</strong>优化：先上量化、先买卡、先切块，每一步都拿到两位数的改善，而数量级的项原封不动——半年后账单回到原点。缺的是一张排序表：哪一项改变问题的数量级，哪一项只改变常数。</p><p><span class="marginnote">直觉类比：搬家想省钱，正确的顺序是先扔东西（数量级），再讲纸箱价（常数）；反过来先讲价、照单全收，箱子打八折，车还是得叫三辆。量化、买卡、切块都是「给纸箱讲价」——每步都有两位数改善，但「要搬的东西太多」这个数量级问题没动，账单迟早涨回去。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>六步，按数量级排序。第一步<strong>少算</strong>：检索圈定（<a href="/llm/lc-retrieval-hybrid-serving">混合服务课</a>）。先召回圈定 5 到 10 份，再对圈定材料通读：单问从 500K 降到 40K，一个数量级；多跳问题召回不足，接<a href="/llm/multi-hop-retrieval">多跳迭代</a>，由门禁的任务族分数触发。第二步<strong>共享</strong>：库级前缀段加会话缓存（<a href="/llm/lc-context-cache-tiers">分层课</a>、<a href="/llm/lc-multidoc-workload">多文档课</a>）。40K 里约 32K 是库的稳定段，进共享前缀；命中后 prefill 只付 8K 增量，语料 KV 只付一份。第三步<strong>调度</strong>：<a href="/llm/lc-chunked-prefill">切块与 token 预算</a>钉住交错延迟，流量涨后把前填<a href="/llm/pd-disaggregation">分池</a>——账不变，尾部变了，p99 进合同。第四步<strong>压便宜</strong>：KV 8-bit（<a href="/llm/kv-longcontext-budget">预算课</a>降级链第一档，<a href="/llm/kv-quant-int8-int4">量化口径</a>）：每 token 64 KiB，容量翻倍、扫描减半，一张表两处兑现。第五步<strong>搬家</strong>：会话级 <a href="/llm/kv-offload">offload</a> 到主机，峰值并发翻倍，恢复零点几秒级。第六步<strong>守门</strong>：每次变更重跑分任务族门禁——链条越长，未被告知的回归越多。</p><p><span class="marginnote">数字实例：单问账怎么从 64 GiB 走到 0.5 GiB。FP16 下每 token KV 是 128 KiB：\\(500\\mathrm{K}\\times128\\,\\text{KiB}=64\\) GiB，装不下；圈定到 40K 是 5 GiB；8K 增量再切 8-bit（64 KiB/token）就是 \\(8\\mathrm{K}\\times64\\,\\text{KiB}=0.5\\) GiB——128 倍里，圈定贡献 12 倍，共享贡献 5 倍，量化贡献 2 倍，顺序就是杠杆大小。</span></p>',9)),(t(),A(i,null,{default:e(()=>[o(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22%E5%9F%BA%E7%BA%BF%EF%BC%9A%E6%AF%8F%E9%97%AE%20500K%20%E5%85%A8%E6%96%87%EF%BC%8C64%20GiB%20KV%22%5D%20--%3E%20S1%5B%22%E5%B0%91%E7%AE%97%EF%BC%9A%E6%A3%80%E7%B4%A2%E5%9C%88%E5%AE%9A%E5%88%B0%2040K%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%85%B1%E4%BA%AB%EF%BC%9A%E7%A8%B3%E5%AE%9A%E6%AE%B5%E5%85%A5%E5%89%8D%E7%BC%80%EF%BC%8C%E5%A2%9E%E9%87%8F%208K%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E8%B0%83%E5%BA%A6%EF%BC%9A%E5%88%87%E5%9D%97%E9%92%89%E5%B0%BE%E9%83%A8%EF%BC%8C%E6%B6%A8%E5%90%8E%E5%88%86%E6%B1%A0%22%5D%0A%20%20S3%20--%3E%20S4%5B%22%E5%8E%8B%E4%BE%BF%E5%AE%9C%EF%BC%9AKV%208-bit%EF%BC%8C%E5%AE%B9%E9%87%8F%E4%B8%8E%E5%B8%A6%E5%AE%BD%E5%8F%8C%E5%85%91%E7%8E%B0%22%5D%0A%20%20S4%20--%3E%20S5%5B%22%E6%90%AC%E5%AE%B6%EF%BC%9A%E4%BC%9A%E8%AF%9D%20offload%20%E6%89%9B%E5%B3%B0%22%5D%0A%20%20S5%20--%3E%20S6%5B%22%E5%AE%88%E9%97%A8%EF%BC%9A%E5%8F%98%E6%9B%B4%E9%87%8D%E8%B7%91%E5%88%86%E4%BB%BB%E5%8A%A1%E6%97%8F%E9%97%A8%E7%A6%81%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[a("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,[a("排序的原理是数量级优先：第一步改变 \\(n\\) 的数量级（约 10 倍），第二步改变复用结构（再数倍），后面四步各拿 2 倍上下。顺序颠倒的代价是真实的：不先圈定就上量化，是在优化线性常数、放过数量级项；不先共享就扩容，是按无共享的账买卡——采购按条数算、账按"),l("a",{href:"/llm/lc-memory-account"},"积"),a("算，差出的倍数全变成闲置算力。每步的账用同一张表记：单问显存·时间积、每百万 token 成本、各任务族门禁分数，三列对齐，哪一步的杠杆用尽一目了然。")],-1)),(t(),A(i,null,{default:e(()=>[o(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20OK%5B%22%E6%AD%A3%E7%A1%AE%E9%A1%BA%E5%BA%8F%3A%E5%85%88%E6%95%B0%E9%87%8F%E7%BA%A7%E5%90%8E%E5%B8%B8%E6%95%B0%22%5D%0A%20%20%20%20A1%5B%22%E5%9C%88%E5%AE%9A%3A500K%20%E5%88%B0%2040K%22%5D%20--%3E%20B1%5B%22%E5%85%B1%E4%BA%AB%3A%E5%A2%9E%E9%87%8F%208K%22%5D%0A%20%20%20%20B1%20--%3E%20C1%5B%22%E9%87%8F%E5%8C%96%20%2F%20%E8%B0%83%E5%BA%A6%20%2F%20offload%3A%E5%90%84%E6%8B%BF%E5%B8%B8%E6%95%B0%E5%80%8D%22%5D%0A%20%20end%0A%20%20subgraph%20BAD%5B%22%E4%B9%B1%E5%BA%8F%3A%E5%85%88%E5%B8%B8%E6%95%B0%E5%90%8E%E6%95%B0%E9%87%8F%E7%BA%A7%22%5D%0A%20%20%20%20A2%5B%22%E5%85%88%E9%87%8F%E5%8C%96%3A%E7%9C%81%202%20%E5%80%8D%22%5D%20--%3E%20B2%5B%22%E5%86%8D%E6%89%A9%E5%AE%B9%E4%B9%B0%E5%8D%A1%3A%E6%8C%89%E6%9D%A1%E6%95%B0%E7%AE%97%E8%B4%A6%22%5D%0A%20%20%20%20B2%20--%3E%20C2%5B%22%E5%8D%95%E9%97%AE%E4%BB%8D%E6%98%AF%20500K%2C%E5%8D%A1%E5%86%8D%E5%A4%9A%E4%B9%9F%E5%9C%A8%E6%90%AC%E5%85%A8%E9%A2%9D%20KV%22%5D%0A%20%20end%0A%20%20OK%20-.%20%22%E5%90%8C%E6%A0%B7%E7%9A%84%E9%92%B1%2C%E7%BB%88%E7%82%B9%E5%B7%AE%E4%B8%80%E4%B8%AA%E6%95%B0%E9%87%8F%E7%BA%A7%22%20.-%3E%20BAD%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">常见误区：「先把卡加一倍，问题就解决了」。扩容提高的是并行度，不改变单个请求要搬的 KV 总量——单问 64 GiB 还是 64 GiB，只是有更多卡一起搬。账单按卡数翻倍，单问成本几乎没动。先把问题变小（圈定、共享），扩容才花在刀刃上。</span></p><p><span class="marginnote">同一条链的账：每问 500K 全文是 64 GiB KV（FP16）；圈定加共享后，8K 增量在 8-bit 下是 0.5 GiB，且大头是只付一次的共享段。两个数量级来自前两步，后四步各拿常数百分比——这是「先少算、再共享」永远排在「先量化」前面的算术原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>数字是量级演示，换库、换模型、换流量结构要重算——账的纪律比数可靠。案例未覆盖的项：嵌入与索引侧的成本（属检索栈）、跨区域传输、冷启动。链条不是单向楼梯：流量结构变了——从查数变成比对、从单人变成全员——第一步的圈定比例与第二步的树组织都要回头重调，六步是循环不是瀑布。最后，每一步都必须过门禁再放量：成本优化的每刀都砍在某组旋钮上，砍完不测，省下的是钱，赔上的是质量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>六步顺序按数量级排：少算、共享、调度、压便宜、搬家、守门；前两步拿数量级，后四步拿常数。</li><li>乱序优化的代价可预测：先量化或先扩容，都在优化常数、放过数量级。</li><li>统一记账：显存·时间积、单位成本、门禁分数三列对齐，杠杆用尽可见。</li><li>链条是循环：流量结构变了，圈定比例与树组织回头重调。</li><li>出处：Pope et al., 2022（会计口径）；Zhong et al., DistServe, OSDI 2024（分池经验）；降级链口径同本仓库 KV 预算课。</li></ul>',6))])}const g=n(m,[["render",p]]);export{K as __pageData,g as default};
